const app=document.querySelector('#app');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const tabs=[['reading','Reading'],['vocabulary','Vocabulary'],['grammar','Grammar'],['expression','Expression'],['speaking','Speaking'],['writing','Writing']];
const storageKey='sprachraum.sessions.v1';
let sessions=Object.create(null),last=null,state=null,view='welcome',drawer=null,returnFocus=null,toastTimer,storageOK=true;
try{const raw=JSON.parse(localStorage.getItem(storageKey)||'null');if(raw?.version===1&&raw.sessions&&typeof raw.sessions==='object'){for(const [id,s]of Object.entries(raw.sessions)){if(s&&typeof s.topic==='string'&&tabs.some(t=>t[0]===s.tab)&&['release','calm','intent','custom'].includes(s.lesson)){sessions[id]={...s,pages:s.pages||{},drafts:s.drafts||{},saved:Array.isArray(s.saved)?s.saved:[],tones:s.tones||{},checks:s.checks||{},reveals:s.reveals||{}};}}last=typeof raw.last==='string'&&sessions[raw.last]?raw.last:null;}}catch{storageOK=false;}
const key=()=>pages()[pageIndex()].id || `${state.tab}:${pageIndex()}`;
const lesson=()=>LESSONS[state.lesson]||{title:state.topic,goal:'Add material and work through it with your teacher.'};
const pageIndex=()=>Math.max(0,Math.min(Number(state.pages[state.tab])||0,pages().length-1));
function pages(){if(state.lesson!=='custom')return lesson()[state.tab];const base={reading:['Read together','Paste a short text or dialogue.','Which part would you like to discuss?'],vocabulary:['Build the word cluster','Add related words, examples, and useful distinctions.','Which words overlap? Where do they differ?'],grammar:['Try a sentence pattern','Add a pattern and a worked example.','Can you use the pattern in a new sentence?'],expression:['Find the words for it','Write what you mean, the situation, and who you are talking to.','What do you want the other person to understand?'],speaking:['Start the conversation','Set a situation and a role for each person.','Listen to your partner and respond to what they say.'],writing:['Write it yourself','Set a reader, a situation, and a short writing task.','What do you want to communicate?']}[state.tab];return [{title:base[0],kicker:'Your material',kind:'custom',lead:base[1],question:base[2],coach:'Add and revise material together. No generated lesson is attached to this topic.',prompt:'Your response'}];}
function persist(){if(state)sessions[state.id]=state;try{localStorage.setItem(storageKey,JSON.stringify({version:1,last,sessions}));storageOK=true;}catch{storageOK=false;}document.querySelectorAll('[data-storage]').forEach(el=>el.textContent=storageOK?'Saved in this browser':'Kept for this visit only · storage unavailable');}
function notify(msg){clearTimeout(toastTimer);const el=document.querySelector('#toast');el.textContent=msg;el.classList.add('show');toastTimer=setTimeout(()=>el.classList.remove('show'),2200);}
function welcome(){closeDrawer(false);view='welcome';app.innerHTML=`<div class="welcome"><header class="topbar"><div class="brand"><span class="mark" aria-hidden="true">»</span>sprachraum</div><span class="meta">DEUTSCH · C1</span></header><main class="welcome-main"><p class="eyebrow">Your next lesson</p><h1>What do you want<br>to learn today?</h1><form class="topic-form" id="topic-form"><input id="topic" aria-label="What do you want to learn today?" placeholder="A topic, a word, something you want to say…" maxlength="240" required autocomplete="off"><button class="start" aria-label="Open lesson">↗</button></form><div class="example">Try <button data-start="ankündigen, erscheinen, veröffentlichen">ankündigen, erscheinen, veröffentlichen</button></div>${last?`<button class="resume" data-resume>Continue: ${esc(LESSONS[sessions[last].lesson]?.title||sessions[last].topic)} →</button>`:''}</main><footer class="welcome-foot">For your 1:1 German lesson <span aria-hidden="true"> · </span><button class="source-button" data-about>3 prepared topics & about</button></footer></div>`;document.querySelector('#topic-form').onsubmit=e=>{e.preventDefault();const input=document.querySelector('#topic');if(!input.value.trim()){input.setCustomValidity('Enter a topic, word, or sentence.');input.reportValidity();input.oninput=()=>input.setCustomValidity('');return;}start(input.value)};bind();}
function detect(topic){const q=topic.toLowerCase().trim();if(/beruhig|runterkomm|abschalten|checking in|check[- ]in|emotional recovery/.test(q))return 'calm';if(/kennenlern|geborgen|kuschel|warmth|boundar|grenzen setzen|say.*what.*mean|saying what i mean|express myself|mich ausdr|sich ausdr/.test(q)||q==='ausdruck')return 'intent';if(/ank[uü]nd|ver[oö]ffentlich|erschein|herausbringen|herausgeben|release(s)? (and|&) announcement|releases & announcements|announcing|publishing|publication/.test(q)||['release','releases','ankündigen, erscheinen, veröffentlichen'].includes(q))return 'release';return 'custom';}
function start(topic,forced){if(typeof topic!=='string'||!topic.trim())throw new Error('Enter a topic.');topic=topic.trim().slice(0,240);const type=forced||detect(topic);if(!['release','calm','intent','custom'].includes(type))throw new Error('Unknown prepared topic.');const id=type==='custom'?`custom:${topic.toLowerCase()}`:type;state=sessions[id]||{id,topic,lesson:type,tab:LESSONS[type]?.start||'reading',pages:{},drafts:{},saved:[],tones:{},checks:{},reveals:{}};last=id;view='session';closeDrawer(false);persist();render();focusTitle();return {topic:lesson().title,area:state.tab,prepared:type!=='custom'};}
function focusTitle(){const title=document.querySelector('#page-title');title?.focus({preventScroll:true});const canvas=document.querySelector('.canvas');if(canvas&&canvas.getBoundingClientRect().top<0)canvas.scrollIntoView({block:'start'});}
function navigate(tab,index){if(!state)throw new Error('Start a lesson first.');if(!tabs.some(t=>t[0]===tab))throw new Error('Unknown lesson area.');state.tab=tab;if(index!==undefined){if(!Number.isInteger(index)||index<0||index>=pages().length)throw new Error('Page does not exist.');state.pages[tab]=index;}closeDrawer(false);persist();render();focusTitle();}
function move(delta){const i=pageIndex(),n=pages().length,ti=tabs.findIndex(t=>t[0]===state.tab);if(delta>0&&i===n-1){if(ti===tabs.length-1){openDrawer('notes');return;}navigate(tabs[ti+1][0],0);}else if(delta<0&&i===0){if(ti>0){const prev=tabs[ti-1][0];navigate(prev,(LESSONS[state.lesson]?.[prev]?.length||1)-1);}}else navigate(state.tab,i+delta);}
function markup(text){return esc(text).replace(/\[\[([^\]]+)\]\]/g,(_,w)=>`<button class="word-link" data-word="${w}">${w}</button>`);}
function saveButton(text){return `<button class="save-word" data-save="${esc(text)}">＋ Keep this phrase</button>`;}
function countWords(value){return (String(value).match(/\p{L}[\p{L}\p{M}’'–-]*|\d+/gu)||[]).length;}
function articleParagraphs(paragraphs,startAt=1){return '<div class="reading long-reading" lang="de">'+paragraphs.map((t,i)=>'<p><span class="paragraph-number" aria-label="Absatz '+(i+startAt)+'">'+(i+startAt)+'</span>'+markup(t)+'</p>').join('')+'</div>';}
function draftLabel(k){for(const [area] of tabs){const page=LESSONS[state.lesson]?.[area]?.find(p=>p.id===k);if(page)return tabs.find(t=>t[0]===area)[1]+' · '+page.title;}if(k==='conversation')return 'Conversation notes';if(k.startsWith('material:'))return 'Your lesson material';const [area,index]=k.split(':');return (tabs.find(t=>t[0]===area)?.[1]||area)+' · '+(Number.isInteger(Number(index))?'earlier activity '+(Number(index)+1):'saved draft');}
function material(p){let html=`<h2 id="page-title" tabindex="-1">${esc(p.title)}</h2>${p.lead?`<p class="intro">${esc(p.lead)}</p>`:''}`;
if(p.kind==='article'){html+='<div class="article-meta"><span>'+esc(p.genre||'Lesetext')+'</span><span>'+countWords(p.paragraphs.join(' '))+' Wörter</span><span>'+p.paragraphs.length+' Absätze</span></div>'+articleParagraphs(p.paragraphs)+'<p class="byline">Originaltext für diese Lektion · Absatznummern für die gemeinsame Besprechung</p>';}
if(p.tasks)html+='<ol class="reading-tasks" lang="de">'+p.tasks.map(q=>'<li><span class="task-reference">Absatz '+esc(q.paragraphs.join(', '))+'</span><p>'+esc(q.question)+'</p></li>').join('')+'</ol>';
if(p.reference)html+='<details class="text-reference"><summary>Lesetext nachschlagen</summary>'+articleParagraphs(p.reference)+'</details>';
if(p.kind==='reading')html+=`<div class="reading" lang="de">${p.paragraphs.map(t=>`<p>${markup(t)}</p>`).join('')}</div><div class="byline">${p.paragraphs.some(t=>t.includes('[['))?'Select a highlighted word to look closer.':'Original practice material.'}</div>`;
if(p.kind==='dialogue')html+=`<div class="dialogue">${p.lines.map(([who,text])=>`<div class="line"><span class="speaker">${esc(who)}</span><span lang="${p.lang||(p.source==='speaking'?'en':'de')}">${esc(text)}</span></div>`).join('')}</div>`;
if(p.kind==='words')html+=`<div class="rows">${p.words.map(([word,meaning,example])=>`<div class="word-row"><div><strong lang="de">${esc(word)}</strong><span>${esc(meaning)}</span></div><p class="de" lang="de">${esc(example)}</p></div>`).join('')}</div>`;
if(p.kind==='pattern')html+=p.patterns.map(([de,en])=>`<div class="pattern"><div class="de" lang="de">${esc(de)}</div><p>${esc(en)}</p></div>`).join('');
if(p.kind==='phrases')html+=`<div class="phrases">${p.phrases.map(([tag,de,note])=>`<div class="phrase"><span class="pill">${esc(tag)}</span><div class="de" lang="de">${esc(de)}</div><p>${esc(note)}</p>${saveButton(de)}</div>`).join('')}</div>`;
if(p.kind==='tone'){const tone=p.tones.find(t=>t[0]===state.tones[key()])||p.tones[0];html+=`${p.original?`<p class="block-title">Starting sentence</p><div class="original" lang="de">${esc(p.original)}</div>`:''}<div class="tones" role="group" aria-label="Choose a tone">${p.tones.map(([id,label])=>`<button class="tone ${id===tone[0]?'selected':''}" data-tone="${id}" aria-pressed="${id===tone[0]}">${esc(label)}</button>`).join('')}</div><div class="tone-result"><p class="quote" lang="de">${esc(tone[2])}</p><p class="hint">${esc(tone[3])}</p>${saveButton(tone[2])}</div>`;}
if(p.reuse){const previous=state.drafts[p.reuse];html+=`<p class="block-title">Your earlier draft</p>${previous?`<div class="prior-draft" lang="de">${esc(previous)}</div>`:`<p class="hint">Your previous page has no draft yet. You can write one there or start here.</p><button class="secondary" data-page="0">Previous writing task</button>`}`;}
if(p.kind==='writing')html+=`<label class="response-label" for="response">${esc(p.prompt)}</label><textarea id="response" class="draft writing-draft" data-draft="${key()}" placeholder="Schreib hier …" lang="de">${esc(state.drafts[key()]||'')}</textarea>${p.targetWords?`<div class="writing-measure"><span data-word-count>${countWords(state.drafts[key()]||'')} Wörter</span><span>Richtwert: ${esc(p.targetWords)} Wörter</span></div>`:''}<span class="local-state" data-storage>${storageOK?'Saved in this browser':'Kept for this visit only · storage unavailable'}</span>`;
if(p.kind==='custom')html+=`<label class="response-label" for="custom-material">Material for this area</label><textarea id="custom-material" class="draft custom-material" data-draft="material:${key()}" placeholder="${esc(p.lead)}">${esc(state.drafts[`material:${key()}`]||'')}</textarea><span class="local-state" data-storage>${storageOK?'Saved in this browser':'Kept for this visit only · storage unavailable'}</span>`;
if(p.criteria)html+='<div class="revision-criteria"><p class="block-title">Bei der Überarbeitung prüfen</p><ul lang="de">'+p.criteria.map(c=>'<li>'+esc(c)+'</li>').join('')+'</ul></div>';
if(p.extension)html+='<details class="text-reference extension"><summary>Vertiefung: '+esc(p.extension.title)+'</summary><p lang="de">'+esc(p.extension.task)+'</p></details>';
return html;}
function activity(p){const c=state.checks[key()];return `<p class="eyebrow">${p.check?'Try it':'With your teacher'}</p><h3 lang="${p.kind==='custom'?'en':'de'}">${esc(p.question)}</h3><p>${esc(p.coach)}</p>${p.check?`<div class="options" role="group" aria-label="Answer choices">${p.check.options.map((option,i)=>`<button class="option ${c?.selected===i?'selected':''}" data-option="${i}" aria-pressed="${c?.selected===i}" lang="de">${esc(option)}</button>`).join('')}</div>${c?.checked?`<div class="feedback ${c.selected===p.check.correct?'':'retry'}" role="status">${esc(p.check.feedback[c.selected])}</div>`:''}<button class="secondary" data-check ${c?.selected===undefined?'disabled':''}>Check answer</button>`:''}${p.kind!=='writing'?`<div class="response-wrap"><label class="response-label" for="response">${esc(p.prompt||'Your notes')}</label><textarea id="response" class="draft" data-draft="${key()}" placeholder="A word, a sentence, a question…" lang="de">${esc(state.drafts[key()]||'')}</textarea><span class="local-state" data-storage>${storageOK?'Saved in this browser':'Kept for this visit only · storage unavailable'}</span></div>`:''}${p.model?`<details class="reveal" data-reveal ${state.reveals[key()]?'open':''}><summary>One possible answer</summary><p lang="de" class="model-answer">${esc(p.model)}</p>${saveButton(p.model)}</details>`:''}${p.kind==='writing'?'<div class="teacher-prompt">Read your writing aloud together. Discuss the choices you made.</div>':''}`;}
function render(){if(!state)return welcome();view='session';const l=lesson(),p=pages()[pageIndex()],i=pageIndex(),ti=tabs.findIndex(t=>t[0]===state.tab),lastPage=i===pages().length-1;app.innerHTML=`<div class="app-shell"><header class="topbar"><button class="brand" data-home aria-label="Sprachraum home"><span class="mark" aria-hidden="true">»</span>sprachraum</button><div class="header-actions"><span class="meta">DEUTSCH · C1</span><button class="quiet" data-home>＋ <span class="new-label">New topic</span></button><button class="secondary" data-notes>Notebook${state.saved.length?` <span class="note-count">${state.saved.length}</span>`:''}</button></div></header><section class="session-heading"><div><p class="eyebrow">Today's lesson</p><h1>${esc(l.title)}</h1><p>${esc(l.goal)}</p></div><span class="session-tag">1:1 lesson workspace</span></section><nav class="tabs-wrap" aria-label="Lesson areas"><div class="tabs">${tabs.map(([id,label],j)=>`<button class="tab ${state.tab===id?'active':''}" data-tab="${id}" aria-current="${state.tab===id?'page':'false'}"><span class="tab-num">0${j+1}</span>${label}</button>`).join('')}</div></nav><main class="main">${state.lesson==='custom'?'<div class="custom-message">This topic has no prepared lesson yet. Add material below with your teacher, or <button class="source-button" data-about>open a prepared topic</button>.</div>':''}<section class="canvas ${p.kind==='article'?'longform':''}" aria-labelledby="page-title"><header class="canvas-top"><p class="eyebrow">${esc(p.kicker)}</p><div class="pages"><span>Page ${i+1} of ${pages().length}</span>${pages().map((pg,j)=>`<button class="page-dot ${i===j?'current':''}" data-page="${j}" aria-label="Page ${j+1}: ${esc(pg.title)}" aria-current="${i===j?'step':'false'}">${j+1}</button>`).join('')}</div></header><div class="canvas-grid"><article class="material">${material(p)}</article><aside class="activity">${activity(p)}</aside></div><footer class="canvas-bottom"><span class="footnote"><span>${state.tab==='expression'?'Ausdruck · intention, wording & tone':state.tab==='vocabulary'?'Wortschatz · related words in context':state.tab==='speaking'?'Sprechen & Zuhören · listen and respond':'Read, try, and discuss together'}</span></span><div class="bottom-actions"><button class="quiet" data-prev ${i===0&&ti===0?'disabled':''}>← Back</button><button class="primary" data-next>${!lastPage?'Next page':ti===tabs.length-1?'Open notebook':`Next: ${esc(tabs[ti+1][1])}`} <span aria-hidden="true">→</span></button></div></footer></section><div class="below"><span>Shared screen or screen share · notes saved on this device</span><button class="source-button" data-source>Lesson sources</button></div></main></div>`;bind();}
function bind(){const all=(sel,fn)=>document.querySelectorAll(sel).forEach(el=>el.onclick=()=>fn(el));all('[data-start]',b=>start(b.dataset.start,b.dataset.lesson));all('[data-home]',welcome);all('[data-resume]',()=>{state=sessions[last];view='session';render();focusTitle()});all('[data-tab]',b=>navigate(b.dataset.tab));all('[data-page]',b=>navigate(state.tab,Number(b.dataset.page)));all('[data-prev]',()=>move(-1));all('[data-next]',()=>move(1));all('[data-notes]',()=>openDrawer('notes'));all('[data-about]',()=>openDrawer('about'));all('[data-source]',()=>openDrawer('source'));all('[data-close]',()=>closeDrawer());all('[data-word]',b=>openDrawer('word',b.dataset.word));all('[data-save]',b=>savePhrase(b.dataset.save));all('[data-tone]',b=>{state.tones[key()]=b.dataset.tone;persist();render();document.querySelector(`[data-tone="${b.dataset.tone}"]`)?.focus({preventScroll:true})});all('[data-option]',b=>{state.checks[key()]={...state.checks[key()],selected:Number(b.dataset.option),checked:false};persist();render();document.querySelector(`[data-option="${b.dataset.option}"]`)?.focus({preventScroll:true})});all('[data-check]',()=>{const c=state.checks[key()];if(c?.selected===undefined)return;c.checked=true;c.attempts=(c.attempts||0)+1;persist();render();document.querySelector('[data-check]')?.focus({preventScroll:true})});all('[data-export]',exportNotes);all('[data-remove]',b=>{state.saved.splice(Number(b.dataset.remove),1);persist();openDrawer('notes')});document.querySelectorAll('[data-draft]').forEach(el=>el.oninput=()=>{state.drafts[el.dataset.draft]=el.value;persist();const counter=document.querySelector('[data-word-count]');if(counter&&el.id==='response')counter.textContent=countWords(el.value)+' Wörter'});document.querySelector('[data-reveal]')?.addEventListener('toggle',e=>{state.reveals[key()]=e.target.open;persist()});}
function savePhrase(text){if(!state)return;if(state.saved.some(n=>n.text===text)){notify('Already in your notebook');return;}state.saved.push({text,area:state.tab,page:pages()[pageIndex()].title});persist();notify('Phrase saved to your notebook');const button=document.querySelector('[data-notes]');if(button)button.innerHTML=`Notebook <span class="note-count">${state.saved.length}</span>`;}
function closeDrawer(restore=true){document.querySelector('.drawer-backdrop')?.remove();document.querySelector('.drawer')?.remove();document.body.style.overflow='';drawer=null;const shell=app.firstElementChild;if(shell)shell.inert=false;if(restore&&returnFocus?.isConnected)returnFocus.focus();}
function openDrawer(type,word){const hadDrawer=!!drawer;if(!hadDrawer)returnFocus=document.activeElement;closeDrawer(false);drawer=type;const p=state?pages()[pageIndex()]:null;let title='',body='';if(type==='notes'){title='Your notebook';const entries=Object.entries(state.drafts).filter(([k,v])=>v.trim()&&!k.startsWith('material:')&&k!=='conversation');body=`<p class="intro">${esc(lesson().title)}<br>Saved on this device. You can download a copy.</p>${state.saved.length?'<p class="block-title">Kept phrases</p>':''}${state.saved.map((n,i)=>`<div class="note"><h3>${esc(n.page)}</h3><p lang="de">${esc(n.text)}</p><button class="source-button" data-remove="${i}">Remove</button></div>`).join('')}${entries.length?'<p class="block-title">Your writing & notes</p>':''}${entries.map(([k,v])=>{const [tab,index]=k.split(':');return `<div class="note"><h3>${esc(draftLabel(k))}</h3><p lang="de">${esc(v)}</p></div>`}).join('')}${!entries.length&&!state.saved.length?'<p class="notebook-empty">Write in a lesson page or keep a phrase. It will appear here.</p>':''}<div class="note"><label for="teacher-notes" class="response-label">Notes from the conversation</label><textarea id="teacher-notes" class="draft" data-draft="conversation" placeholder="A correction, an example, something to revisit…">${esc(state.drafts.conversation||'')}</textarea><span class="local-state" data-storage>${storageOK?'Saved in this browser':'Kept for this visit only · storage unavailable'}</span></div><button class="primary" data-export>Download lesson notes ↓</button>`;}
if(type==='about'){title='About this prototype';body=`<p class="intro">A workspace for a teacher and learner using one screen or screen share. Each area has its own material and pages.</p><p class="block-title">Prepared topics</p>${Object.entries(LESSONS).map(([id,l])=>`<button class="topic-choice" data-start="${esc(l.label)}" data-lesson="${id}">${esc(l.label)} <span>↗</span></button>`).join('')}<p class="intro">The three prepared topics now include longer readings, close reading, discussion, and substantial writing. Extension tasks ask for more independent analysis. These are original teaching examples, not certified level tests.</p><p class="intro">Other topics open an editable lesson workspace. This prototype does not generate lessons or assess free writing with AI.</p><p class="intro">Notes are stored in this browser. There is no live sync between devices.</p><p class="block-title">Source material</p><p class="intro">100 C1 PDFs, 2,978 pages. The archives contain reading (36), speaking (36), grammar (12), communication (12), and writing (4) lessons.</p><p class="intro">Vocabulary and Expression bring recurring work from those lessons into permanent areas. All examples in this prototype are newly written. The original PDFs and private conversation are not included.</p>`;}
if(type==='source'){title='Lesson sources';const s=SOURCE_PATTERNS[p.source];body=s?`<p class="intro">The activity structure draws on the source below. The text, examples, and prompts on this page are newly written.</p><div class="source-item"><span class="pill">${esc(s.volume)} · pp. ${esc(s.pages)}</span><h3>${esc(s.title)}</h3><p>${esc(s.file)}.pdf</p><p>${esc(s.note)}</p></div><p class="intro">C1 is the level of the source collection. The longer readings and extension tasks have not been independently level-tested. No C2 source collection was supplied.</p><button class="secondary" data-about>All topics & prototype details</button>`:'<p class="intro">This is your own material. There is no PDF source attached.</p>';}
if(type==='word'){title=word;const aliases={'kündigt':'ankündigen','an':'ankündigen','erscheint':'erscheinen','Veröffentlichung':'die Veröffentlichung','Ausgabe':'die Ausgabe','bringt':'herausbringen','heraus':'herausbringen','Neuerscheinungen':'die Neuerscheinung'};const term=aliases[word]||word;const row=LESSONS.release.vocabulary.flatMap(p=>p.words||[]).find(w=>w[0]===term);body=row?`<span class="pill">Wortschatz</span><h3 lang="de">${esc(row[0])}</h3><p class="intro">${esc(row[1])}</p><p class="quote" lang="de">${esc(row[2])}</p>${saveButton(`${row[0]} — ${row[2]}`)}<div style="margin-top:30px"><button class="secondary" data-tab="vocabulary">Open the full word cluster →</button></div>`:`<p class="intro">Discuss this word in context with your teacher.</p>${saveButton(word)}`;}
app.insertAdjacentHTML('beforeend',`<div class="drawer-backdrop" data-close></div><aside class="drawer" role="dialog" aria-modal="true" aria-labelledby="drawer-title"><div class="drawer-head"><span class="eyebrow" style="margin:0">Sprachraum</span><button class="quiet" data-close aria-label="Close panel">✕</button></div><h2 id="drawer-title">${esc(title)}</h2>${body}</aside>`);document.body.style.overflow='hidden';app.firstElementChild.inert=true;bind();document.querySelector('.drawer [data-close]').focus();}
function exportNotes(){const lines=[lesson().title,'','Your topic: '+state.topic,'','SAVED PHRASES',...state.saved.map(n=>n.text),'','YOUR WRITING & NOTES',...Object.entries(state.drafts).filter(([,v])=>v.trim()).map(([k,v])=>`${draftLabel(k)}\n${v}`)];const blob=new Blob([lines.join('\n\n')],{type:'text/plain;charset=utf-8'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='sprachraum-lesson-notes.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Lesson notes downloaded');}
document.addEventListener('keydown',e=>{if(!drawer)return;if(e.key==='Escape'){e.preventDefault();closeDrawer()}if(e.key==='Tab'){const focusable=[...document.querySelectorAll('.drawer button,.drawer textarea,.drawer a')].filter(e=>!e.disabled);const first=focusable[0],lastEl=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();lastEl?.focus()}else if(!e.shiftKey&&document.activeElement===lastEl){e.preventDefault();first?.focus()}}});
welcome();
if(document.modelContext?.registerTool){const lifecycle=new AbortController();const definitions=[{name:'read_lesson_state',description:'Read the current topic, lesson area, page, and draft. Does not change anything.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:()=>({view,topic:state?lesson().title:null,area:state?.tab,page:state?pageIndex()+1:null,draft:state?.drafts[key()]||''})},{name:'start_lesson',description:'Open one of the three prepared topics, or an editable workspace for another topic.',inputSchema:{type:'object',properties:{topic:{type:'string',minLength:1,maxLength:240}},required:['topic'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute:input=>{if(!input||typeof input.topic!=='string'||!input.topic.trim()||input.topic.length>240)throw new Error('Provide a topic from 1 to 240 characters.');return start(input.topic)}},{name:'navigate_lesson',description:'Open a lesson area and an optional one-based page number. Retains all drafts.',inputSchema:{type:'object',properties:{area:{type:'string',enum:tabs.map(t=>t[0])},page:{type:'integer',minimum:1}},required:['area'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:input=>{if(!input||!tabs.some(t=>t[0]===input.area))throw new Error('Unknown area.');if(input.page!==undefined&&(!Number.isInteger(input.page)||input.page<1))throw new Error('Page must be a positive integer.');const target=LESSONS[state?.lesson]?.[input.area]?.length||(state?1:0);if(input.page!==undefined&&input.page>target)throw new Error('Page does not exist.');navigate(input.area,input.page===undefined?undefined:input.page-1);return {area:state.tab,page:pageIndex()+1}}}];for(const def of definitions){try{Promise.resolve(document.modelContext.registerTool(def,{signal:lifecycle.signal})).catch(()=>{});}catch{}}addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
